messages.content:
{
 "observed": [
  "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice.",
  "You are at the hotel lobby. A copy of a received telegram is at your hand: Alma's daughter in Pittsburgh has the whole interview. Her reply is 'I know that voice. Play it again.'"
 ],
 "your_retained_experiences": [
  "Phil rides the coach and steps off at Pittsburgh.",
  "Phil sleeps on the Pittsburgh terminal bench.",
  "Rest the body. Be at the door at 8. Move the couch. Do not test the shape. Do not play the bars. Do not sit behind the rig. Be the man in the folding chair at the terminal who is going to be at the door at 8. The thing is the thing. The rest is the rest. Nothing else is required of the evening."
 ],
 "physical_choices": {
  "phone_sister": "Use the open phone return to speak to your sister about the van.",
  "wait_here": "Stay where you are for this first hour.",
  "listen_to_interview": "Listen to the transmitted reel on the radio.",
  "walk_to_depot": "Walk to the local depot. The first coach is at one."
 }
}
